INSERT INTO lessons VALUES('P1A-U01-L1',1,'course-foundations-v1',1,'A',1,'把问候送给朋友','{"id":"P1A-U01-L1","unitId":"P1A-U01","unitTitle":"你好新朋友","grade":1,"term":"A","order":1,"minutes":6,"title":"把问候送给朋友","subtitle":"见面时，先送出一句温暖的话。","topicIds":[],"vocabulary":[{"word":"hello","meaning":"你好"},{"word":"morning","meaning":"早晨"},{"word":"goodbye","meaning":"再见"}],"task":"明天进教室时，试着用英语和老师问早。","cards":[{"title":"把问候送给朋友","rule":"Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","example":"Hello, Mia.","translation":"你好，Mia。"},{"title":"把问候送给朋友","rule":"Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","example":"Good morning, Miss Li.","translation":"李老师，早上好。"},{"title":"把问候送给朋友","rule":"Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","example":"Goodbye, Ben.","translation":"Ben，再见。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P1A-U01-L2',1,'course-foundations-v1',1,'A',1,'说说我是谁','{"id":"P1A-U01-L2","unitId":"P1A-U01","unitTitle":"你好新朋友","grade":1,"term":"A","order":2,"minutes":6,"title":"说说我是谁","subtitle":"把自己的名字放进句子里。","topicIds":["grammar.be"],"vocabulary":[{"word":"I","meaning":"我"},{"word":"name","meaning":"名字"},{"word":"my","meaning":"我的"}],"task":"用I am介绍自己的昵称，家长也来介绍一下自己。","cards":[{"title":"说说我是谁","rule":"介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","example":"I am Mia.","translation":"我是Mia。"},{"title":"说说我是谁","rule":"介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","example":"My name is Ben.","translation":"我的名字是Ben。"},{"title":"说说我是谁","rule":"介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","example":"I am Sam.","translation":"我是Sam。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P1A-U01-L3',1,'course-foundations-v1',1,'A',1,'我和你的句子伙伴','{"id":"P1A-U01-L3","unitId":"P1A-U01","unitTitle":"你好新朋友","grade":1,"term":"A","order":3,"minutes":6,"title":"我和你的句子伙伴","subtitle":"发现I和You各自喜欢的be动词。","topicIds":["grammar.be"],"vocabulary":[{"word":"you","meaning":"你；你们"},{"word":"friend","meaning":"朋友"},{"word":"happy","meaning":"开心的"}],"task":"指着自己说I am happy，再指向家长说You are my friend。","cards":[{"title":"我和你的句子伙伴","rule":"I和am搭配，You和are搭配。You既可以表示你，也可以表示你们。","example":"I am happy.","translation":"我很开心。"},{"title":"我和你的句子伙伴","rule":"I和am搭配，You和are搭配。You既可以表示你，也可以表示你们。","example":"You are my friend.","translation":"你是我的朋友。"},{"title":"我和你的句子伙伴","rule":"I和am搭配，You和are搭配。You既可以表示你，也可以表示你们。","example":"You are ready.","translation":"你准备好了。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P1A-U01-L4',1,'course-foundations-v1',1,'A',1,'新朋友见面会','{"id":"P1A-U01-L4","unitId":"P1A-U01","unitTitle":"你好新朋友","grade":1,"term":"A","order":4,"minutes":6,"title":"新朋友见面会","subtitle":"用学过的问候和介绍完成一个小任务。","topicIds":["grammar.be"],"vocabulary":[{"word":"what","meaning":"什么"},{"word":"your","meaning":"你的"},{"word":"hello","meaning":"你好"}],"task":"和家长分角色完成问候、问名字、介绍自己的三句小对话。","cards":[{"title":"新朋友见面会","rule":"先问候，再介绍自己。听到What''s your name?，可以用My name is…回答。","example":"What is your name?","translation":"你叫什么名字？"},{"title":"新朋友见面会","rule":"先问候，再介绍自己。听到What''s your name?，可以用My name is…回答。","example":"My name is Mia.","translation":"我的名字是Mia。"},{"title":"新朋友见面会","rule":"先问候，再介绍自己。听到What''s your name?，可以用My name is…回答。","example":"Hello! I am Ben.","translation":"你好！我是Ben。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P2A-U01-L1',1,'course-foundations-v1',2,'A',1,'朋友名片上的小线索','{"id":"P2A-U01-L1","unitId":"P2A-U01","unitTitle":"我的新朋友","grade":2,"term":"A","order":1,"minutes":6,"title":"朋友名片上的小线索","subtitle":"用he、she和they介绍不同的人。","topicIds":["grammar.pronouns"],"vocabulary":[{"word":"he","meaning":"他"},{"word":"she","meaning":"她"},{"word":"they","meaning":"他们；她们"}],"task":"找一张家庭合照，用he、she或they介绍其中的人。","cards":[{"title":"朋友名片上的小线索","rule":"he表示他，she表示她，they表示他们或她们。介绍一个人常用is，介绍多个人用are。","example":"She is Mia.","translation":"她是Mia。"},{"title":"朋友名片上的小线索","rule":"he表示他，she表示她，they表示他们或她们。介绍一个人常用is，介绍多个人用are。","example":"He is Ben.","translation":"他是Ben。"},{"title":"朋友名片上的小线索","rule":"he表示他，she表示她，they表示他们或她们。介绍一个人常用is，介绍多个人用are。","example":"They are friends.","translation":"他们是朋友。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P2A-U01-L2',1,'course-foundations-v1',2,'A',1,'年龄也有句子伙伴','{"id":"P2A-U01-L2","unitId":"P2A-U01","unitTitle":"我的新朋友","grade":2,"term":"A","order":2,"minutes":6,"title":"年龄也有句子伙伴","subtitle":"读懂名片，用be说年龄。","topicIds":["grammar.be"],"vocabulary":[{"word":"eight","meaning":"八"},{"word":"nine","meaning":"九"},{"word":"old","meaning":"……岁的"}],"task":"用英语说说自己和家长扮演的玩偶各几岁。","cards":[{"title":"年龄也有句子伙伴","rule":"英语说年龄常用人称加be再加数字。I am eight表示我八岁，不说I have eight。","example":"I am eight.","translation":"我八岁。"},{"title":"年龄也有句子伙伴","rule":"英语说年龄常用人称加be再加数字。I am eight表示我八岁，不说I have eight。","example":"He is nine.","translation":"他九岁。"},{"title":"年龄也有句子伙伴","rule":"英语说年龄常用人称加be再加数字。I am eight表示我八岁，不说I have eight。","example":"They are eight.","translation":"他们都八岁。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P2A-U01-L3',1,'course-foundations-v1',2,'A',1,'找到爱好的共同点','{"id":"P2A-U01-L3","unitId":"P2A-U01","unitTitle":"我的新朋友","grade":2,"term":"A","order":3,"minutes":6,"title":"找到爱好的共同点","subtitle":"用like说喜欢什么。","topicIds":["grammar.pronouns"],"vocabulary":[{"word":"reading","meaning":"阅读"},{"word":"swimming","meaning":"游泳"},{"word":"singing","meaning":"唱歌"}],"task":"问家长喜欢什么活动，试着找到一个共同爱好。","cards":[{"title":"找到爱好的共同点","rule":"I和You后可以直接用like加喜欢的活动。like之后用swimming这类-ing形式表示喜欢做某事。","example":"I like reading.","translation":"我喜欢阅读。"},{"title":"找到爱好的共同点","rule":"I和You后可以直接用like加喜欢的活动。like之后用swimming这类-ing形式表示喜欢做某事。","example":"You like swimming.","translation":"你喜欢游泳。"},{"title":"找到爱好的共同点","rule":"I和You后可以直接用like加喜欢的活动。like之后用swimming这类-ing形式表示喜欢做某事。","example":"I like singing.","translation":"我喜欢唱歌。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P2A-U01-L4',1,'course-foundations-v1',2,'A',1,'向大家介绍我的朋友','{"id":"P2A-U01-L4","unitId":"P2A-U01","unitTitle":"我的新朋友","grade":2,"term":"A","order":4,"minutes":6,"title":"向大家介绍我的朋友","subtitle":"把人物、年龄和爱好连成一张名片。","topicIds":["grammar.be"],"vocabulary":[{"word":"friend","meaning":"朋友"},{"word":"kind","meaning":"友善的"},{"word":"classmate","meaning":"同学"}],"task":"画一张虚构朋友的名片，写名字、年龄，再用英语介绍。","cards":[{"title":"向大家介绍我的朋友","rule":"介绍朋友时，先选对he或she，再和is搭配。换成you或they时，要检查be动词。","example":"She is eight.","translation":"她八岁。"},{"title":"向大家介绍我的朋友","rule":"介绍朋友时，先选对he或she，再和is搭配。换成you或they时，要检查be动词。","example":"We are friends.","translation":"我们是朋友。"},{"title":"向大家介绍我的朋友","rule":"介绍朋友时，先选对he或she，再和is搭配。换成you或they时，要检查be动词。","example":"He is kind.","translation":"他很友善。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P3A-U01-L1',1,'course-foundations-v1',3,'A',1,'身份和拥有要分清','{"id":"P3A-U01-L1","unitId":"P3A-U01","unitTitle":"校园里的我们","grade":3,"term":"A","order":1,"minutes":6,"title":"身份和拥有要分清","subtitle":"be说明是谁，have说明有什么。","topicIds":["grammar.be","grammar.possession"],"vocabulary":[{"word":"student","meaning":"学生"},{"word":"book","meaning":"书"},{"word":"classroom","meaning":"教室"}],"task":"在家找一样自己拥有的物品，再说一说自己的身份。","cards":[{"title":"身份和拥有要分清","rule":"be用来描述身份或状态；have表示拥有。We are students与We have books表达的意思不同。","example":"We are students.","translation":"我们是学生。"},{"title":"身份和拥有要分清","rule":"be用来描述身份或状态；have表示拥有。We are students与We have books表达的意思不同。","example":"We have books.","translation":"我们有书。"},{"title":"身份和拥有要分清","rule":"be用来描述身份或状态；have表示拥有。We are students与We have books表达的意思不同。","example":"I am ready.","translation":"我准备好了。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P3A-U01-L2',1,'course-foundations-v1',3,'A',1,'书包里的have和has','{"id":"P3A-U01-L2","unitId":"P3A-U01","unitTitle":"校园里的我们","grade":3,"term":"A","order":2,"minutes":6,"title":"书包里的have和has","subtitle":"给不同主语选对拥有的表达。","topicIds":["grammar.possession"],"vocabulary":[{"word":"pencil","meaning":"铅笔"},{"word":"ruler","meaning":"尺子"},{"word":"bag","meaning":"书包"}],"task":"挑选三样文具，分别用I have和She has介绍。","cards":[{"title":"书包里的have和has","rule":"I、you、we、they后用have；he、she、it或一个人的名字后用has。","example":"Mia has a pencil.","translation":"Mia有一支铅笔。"},{"title":"书包里的have和has","rule":"I、you、we、they后用have；he、she、it或一个人的名字后用has。","example":"We have rulers.","translation":"我们有尺子。"},{"title":"书包里的have和has","rule":"I、you、we、they后用have；he、she、it或一个人的名字后用has。","example":"I have a blue bag.","translation":"我有一个蓝色的书包。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P3A-U01-L3',1,'course-foundations-v1',3,'A',1,'教室里的单数与复数','{"id":"P3A-U01-L3","unitId":"P3A-U01","unitTitle":"校园里的我们","grade":3,"term":"A","order":3,"minutes":6,"title":"教室里的单数与复数","subtitle":"把一个人和一群人介绍清楚。","topicIds":["grammar.be","grammar.there-be"],"vocabulary":[{"word":"desk","meaning":"课桌"},{"word":"teacher","meaning":"老师"},{"word":"friendly","meaning":"友好的"}],"task":"观察房间里的物品，用There is或There are说一件事。","cards":[{"title":"教室里的单数与复数","rule":"一个人或一个东西常与is搭配；多人或复数东西常与are搭配。They不和is搭配。","example":"There are two desks.","translation":"这里有两张课桌。"},{"title":"教室里的单数与复数","rule":"一个人或一个东西常与is搭配；多人或复数东西常与are搭配。They不和is搭配。","example":"She is our teacher.","translation":"她是我们的老师。"},{"title":"教室里的单数与复数","rule":"一个人或一个东西常与is搭配；多人或复数东西常与are搭配。They不和is搭配。","example":"They are friendly.","translation":"他们很友好。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P3A-U01-L4',1,'course-foundations-v1',3,'A',1,'校园人物小档案','{"id":"P3A-U01-L4","unitId":"P3A-U01","unitTitle":"校园里的我们","grade":3,"term":"A","order":4,"minutes":6,"title":"校园人物小档案","subtitle":"读人物信息，选择身份或拥有。","topicIds":["grammar.be","grammar.possession"],"vocabulary":[{"word":"team","meaning":"团队"},{"word":"library","meaning":"图书馆"},{"word":"new","meaning":"新的"}],"task":"为一个校园小队做档案：介绍他们是谁，以及他们有什么。","cards":[{"title":"校园人物小档案","rule":"先弄清想说谁或什么，再判断句子是在说身份、状态，还是拥有的物品。","example":"Ben is a new student.","translation":"Ben是一名新学生。"},{"title":"校园人物小档案","rule":"先弄清想说谁或什么，再判断句子是在说身份、状态，还是拥有的物品。","example":"Mia has a ruler.","translation":"Mia有一把尺子。"},{"title":"校园人物小档案","rule":"先弄清想说谁或什么，再判断句子是在说身份、状态，还是拥有的物品。","example":"We are library helpers.","translation":"我们是图书馆小帮手。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P4A-U01-L1',1,'course-foundations-v1',4,'A',1,'每天的习惯有规律','{"id":"P4A-U01-L1","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":1,"minutes":6,"title":"每天的习惯有规律","subtitle":"用一般现在时说日常。","topicIds":["tense.present-simple"],"vocabulary":[{"word":"usually","meaning":"通常"},{"word":"study","meaning":"学习"},{"word":"school","meaning":"学校"}],"task":"写出一个真实的小习惯，再把主语换成一个朋友试试看。","cards":[{"title":"每天的习惯有规律","rule":"日常习惯用一般现在时。主语是he、she或一个人的名字时，肯定句中的行为动词常要加-s或-es。","example":"Mia walks to school every day.","translation":"Mia每天步行上学。"},{"title":"每天的习惯有规律","rule":"日常习惯用一般现在时。主语是he、she或一个人的名字时，肯定句中的行为动词常要加-s或-es。","example":"I read every day.","translation":"我每天阅读。"},{"title":"每天的习惯有规律","rule":"日常习惯用一般现在时。主语是he、she或一个人的名字时，肯定句中的行为动词常要加-s或-es。","example":"Ben studies English on Sundays.","translation":"Ben每逢周日学英语。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P4A-U01-L2',1,'course-foundations-v1',4,'A',1,'频率词站在哪里','{"id":"P4A-U01-L2","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":2,"minutes":6,"title":"频率词站在哪里","subtitle":"用usually、often和never说频率。","topicIds":["grammar.frequency"],"vocabulary":[{"word":"often","meaning":"经常"},{"word":"always","meaning":"总是"},{"word":"never","meaning":"从不"}],"task":"说说你经常做的一件事，保留一个符合真实情况的频率词。","cards":[{"title":"频率词站在哪里","rule":"频率副词常放在行为动词前、be动词后，例如usually read、am never late。","example":"I often read at home.","translation":"我经常在家阅读。"},{"title":"频率词站在哪里","rule":"频率副词常放在行为动词前、be动词后，例如usually read、am never late。","example":"I am never late.","translation":"我从不迟到。"},{"title":"频率词站在哪里","rule":"频率副词常放在行为动词前、be动词后，例如usually read、am never late。","example":"Ben usually gets up early.","translation":"Ben通常早起。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P4A-U01-L3',1,'course-foundations-v1',4,'A',1,'问问朋友的小习惯','{"id":"P4A-U01-L3","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":3,"minutes":6,"title":"问问朋友的小习惯","subtitle":"does出现后，行为动词回原形。","topicIds":["sentence.yes-no","tense.present-simple"],"vocabulary":[{"word":"practice","meaning":"练习"},{"word":"early","meaning":"早早地"},{"word":"every","meaning":"每一"}],"task":"问家长一个真实的习惯问题，并留意do或does后面的动词。","cards":[{"title":"问问朋友的小习惯","rule":"一般现在时中，I和you用do提问；he、she或单个人名用does。does后面的行为动词用原形。","example":"Does Mia read every day?","translation":"Mia每天阅读吗？"},{"title":"问问朋友的小习惯","rule":"一般现在时中，I和you用do提问；he、she或单个人名用does。does后面的行为动词用原形。","example":"Do you get up early?","translation":"你早起吗？"},{"title":"问问朋友的小习惯","rule":"一般现在时中，I和you用do提问；he、she或单个人名用does。does后面的行为动词用原形。","example":"Ben does not swim on Sundays.","translation":"Ben周日不游泳。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P4A-U01-L4',1,'course-foundations-v1',4,'A',1,'读懂一份学习日志','{"id":"P4A-U01-L4","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":4,"minutes":6,"title":"读懂一份学习日志","subtitle":"从日志里找到时间线索和动词伙伴。","topicIds":["tense.present-simple","grammar.frequency"],"vocabulary":[{"word":"goal","meaning":"目标"},{"word":"diary","meaning":"日记"},{"word":"Monday","meaning":"星期一"}],"task":"为自己选一个小学习目标，用一句真实的英语习惯句描述。","cards":[{"title":"读懂一份学习日志","rule":"every day、on Mondays等线索常描述习惯，但还要结合整句意思判断，不是只看一个词。","example":"I read at home every day.","translation":"我每天在家阅读。"},{"title":"读懂一份学习日志","rule":"every day、on Mondays等线索常描述习惯，但还要结合整句意思判断，不是只看一个词。","example":"Mia often plays the piano on Mondays.","translation":"Mia经常在周一弹钢琴。"},{"title":"读懂一份学习日志","rule":"every day、on Mondays等线索常描述习惯，但还要结合整句意思判断，不是只看一个词。","example":"I usually start early.","translation":"我通常很早开始。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P5A-U01-L1',1,'course-foundations-v1',5,'A',1,'现在与昨天的两张照片','{"id":"P5A-U01-L1","unitId":"P5A-U01","unitTitle":"我的成长手册","grade":5,"term":"A","order":1,"minutes":6,"title":"现在与昨天的两张照片","subtitle":"用时间线看清动作发生在什么时候。","topicIds":["tense.past-simple","tense.present-simple"],"vocabulary":[{"word":"yesterday","meaning":"昨天"},{"word":"today","meaning":"今天"},{"word":"last","meaning":"上一个的"}],"task":"想一件昨天发生的小事，再说一个平时的习惯，听听动词怎样变化。","cards":[{"title":"现在与昨天的两张照片","rule":"一般现在时可以说习惯，一般过去时可以说过去发生的事。时间线索和句意要一起看。","example":"Mia walks to school every day.","translation":"Mia每天步行上学。"},{"title":"现在与昨天的两张照片","rule":"一般现在时可以说习惯，一般过去时可以说过去发生的事。时间线索和句意要一起看。","example":"Mia walked to the park yesterday.","translation":"Mia昨天步行去了公园。"},{"title":"现在与昨天的两张照片","rule":"一般现在时可以说习惯，一般过去时可以说过去发生的事。时间线索和句意要一起看。","example":"I was tired yesterday.","translation":"我昨天很累。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P5A-U01-L2',1,'course-foundations-v1',5,'A',1,'动词的过去旅行','{"id":"P5A-U01-L2","unitId":"P5A-U01","unitTitle":"我的成长手册","grade":5,"term":"A","order":2,"minutes":6,"title":"动词的过去旅行","subtitle":"认识规则-ed与常用不规则过去式。","topicIds":["forms.regular-past","forms.irregular-past"],"vocabulary":[{"word":"went","meaning":"go的过去式"},{"word":"saw","meaning":"see的过去式"},{"word":"played","meaning":"play的过去式"}],"task":"把went、saw和played各放进一个过去发生的真实或虚构小故事。","cards":[{"title":"动词的过去旅行","rule":"一些过去式直接加-ed，如play变played；有些要单独记，如go变went、see变saw，不能一律加-ed。","example":"Ben went to the library last Sunday.","translation":"Ben上周日去了图书馆。"},{"title":"动词的过去旅行","rule":"一些过去式直接加-ed，如play变played；有些要单独记，如go变went、see变saw，不能一律加-ed。","example":"We saw a bird yesterday.","translation":"我们昨天看见了一只鸟。"},{"title":"动词的过去旅行","rule":"一些过去式直接加-ed，如play变played；有些要单独记，如go变went、see变saw，不能一律加-ed。","example":"Mia played football yesterday.","translation":"Mia昨天踢了足球。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P5A-U01-L3',1,'course-foundations-v1',5,'A',1,'did后面要回到原形','{"id":"P5A-U01-L3","unitId":"P5A-U01","unitTitle":"我的成长手册","grade":5,"term":"A","order":3,"minutes":6,"title":"did后面要回到原形","subtitle":"过去的问句与否定句也有规律。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"vocabulary":[{"word":"did","meaning":"do的过去式；过去时助动词"},{"word":"visit","meaning":"参观；拜访"},{"word":"finish","meaning":"完成"}],"task":"和家长聊一件昨天做过或没做过的事，检查did后面的动词。","cards":[{"title":"did后面要回到原形","rule":"一般过去时的行为动词问句和否定句用了did或did not后，主要动词回到原形；be动词另有was/were的规则。","example":"Did Ben go to the park yesterday?","translation":"Ben昨天去公园了吗？"},{"title":"did后面要回到原形","rule":"一般过去时的行为动词问句和否定句用了did或did not后，主要动词回到原形；be动词另有was/were的规则。","example":"I did not swim yesterday.","translation":"我昨天没有游泳。"},{"title":"did后面要回到原形","rule":"一般过去时的行为动词问句和否定句用了did或did not后，主要动词回到原形；be动词另有was/were的规则。","example":"Did you finish the task?","translation":"你完成任务了吗？"}],"itemCount":9}');
INSERT INTO lessons VALUES('P5A-U01-L4',1,'course-foundations-v1',5,'A',1,'把成长写进小手册','{"id":"P5A-U01-L4","unitId":"P5A-U01","unitTitle":"我的成长手册","grade":5,"term":"A","order":4,"minutes":6,"title":"把成长写进小手册","subtitle":"区别过去的一次经历和现在的日常。","topicIds":["tense.past-simple","tense.present-simple"],"vocabulary":[{"word":"grow","meaning":"成长"},{"word":"learn","meaning":"学习"},{"word":"before","meaning":"以前；在……之前"}],"task":"写一句以前的自己和一句现在的自己，给努力成长的自己留句鼓励。","cards":[{"title":"把成长写进小手册","rule":"比较两段成长记录时，先画出事件的时间，再选合适的动词。不要把did和动词过去式叠在一起。","example":"I was shy before.","translation":"我以前很害羞。"},{"title":"把成长写进小手册","rule":"比较两段成长记录时，先画出事件的时间，再选合适的动词。不要把did和动词过去式叠在一起。","example":"I speak English with friends every day.","translation":"我每天和朋友说英语。"},{"title":"把成长写进小手册","rule":"比较两段成长记录时，先画出事件的时间，再选合适的动词。不要把did和动词过去式叠在一起。","example":"I learned a new song last week.","translation":"我上周学了一首新歌。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P6A-U01-L1',1,'course-foundations-v1',6,'A',1,'从意思出发找时态','{"id":"P6A-U01-L1","unitId":"P6A-U01","unitTitle":"成为自主学习者","grade":6,"term":"A","order":1,"minutes":6,"title":"从意思出发找时态","subtitle":"区分日常、此刻和过去的一次事件。","topicIds":["tense.present-simple","tense.present-continuous","tense.past-simple"],"vocabulary":[{"word":"review","meaning":"复习"},{"word":"strategy","meaning":"策略"},{"word":"now","meaning":"现在"}],"task":"把今天的一件事分成习惯、此刻或过去，再说明你选这种时态的理由。","cards":[{"title":"从意思出发找时态","rule":"日常可用一般现在时，此刻正在发生可用be加-ing，过去的一次事件可用一般过去时。先看意义再选形式。","example":"Mia reads English stories every day.","translation":"Mia每天阅读英语故事。"},{"title":"从意思出发找时态","rule":"日常可用一般现在时，此刻正在发生可用be加-ing，过去的一次事件可用一般过去时。先看意义再选形式。","example":"Mia is reading a story now.","translation":"Mia现在正在读一个故事。"},{"title":"从意思出发找时态","rule":"日常可用一般现在时，此刻正在发生可用be加-ing，过去的一次事件可用一般过去时。先看意义再选形式。","example":"Mia went to the library yesterday.","translation":"Mia昨天去了图书馆。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P6A-U01-L2',1,'course-foundations-v1',6,'A',1,'问句里的小侦探','{"id":"P6A-U01-L2","unitId":"P6A-U01","unitTitle":"成为自主学习者","grade":6,"term":"A","order":2,"minutes":6,"title":"问句里的小侦探","subtitle":"根据问的内容找到助动词。","topicIds":["sentence.yes-no","sentence.wh"],"vocabulary":[{"word":"question","meaning":"问题"},{"word":"answer","meaning":"回答"},{"word":"check","meaning":"检查"}],"task":"给一个朋友设计三个问题，分别问日常、昨天和此刻的事。","cards":[{"title":"问句里的小侦探","rule":"行为动词的一般现在时常用do/does提问，一般过去时常用did提问；正在进行的活动用be动词提问。","example":"When does Mia study?","translation":"Mia什么时候学习？"},{"title":"问句里的小侦探","rule":"行为动词的一般现在时常用do/does提问，一般过去时常用did提问；正在进行的活动用be动词提问。","example":"Did you review yesterday?","translation":"你昨天复习了吗？"},{"title":"问句里的小侦探","rule":"行为动词的一般现在时常用do/does提问，一般过去时常用did提问；正在进行的活动用be动词提问。","example":"Are you reading now?","translation":"你现在正在阅读吗？"}],"itemCount":9}');
INSERT INTO lessons VALUES('P6A-U01-L3',1,'course-foundations-v1',6,'A',1,'学习计划怎样表达','{"id":"P6A-U01-L3","unitId":"P6A-U01","unitTitle":"成为自主学习者","grade":6,"term":"A","order":3,"minutes":6,"title":"学习计划怎样表达","subtitle":"用going to表达打算，用should提出建议。","topicIds":["tense.future","grammar.modals"],"vocabulary":[{"word":"plan","meaning":"计划"},{"word":"should","meaning":"应该；用于建议"},{"word":"tomorrow","meaning":"明天"}],"task":"给明天定一个小计划，再给自己一句照顾身体的建议。","cards":[{"title":"学习计划怎样表达","rule":"be going to加动词原形可以表达打算；should加动词原形用于建议。它们表达的意思不同。","example":"I am going to review tomorrow.","translation":"我明天准备复习。"},{"title":"学习计划怎样表达","rule":"be going to加动词原形可以表达打算；should加动词原形用于建议。它们表达的意思不同。","example":"You should take a break.","translation":"你应该休息一下。"},{"title":"学习计划怎样表达","rule":"be going to加动词原形可以表达打算；should加动词原形用于建议。它们表达的意思不同。","example":"Mia is going to read tomorrow.","translation":"Mia明天打算读书。"}],"itemCount":9}');
INSERT INTO lessons VALUES('P6A-U01-L4',1,'course-foundations-v1',6,'A',1,'写一张自主学习自评卡','{"id":"P6A-U01-L4","unitId":"P6A-U01","unitTitle":"成为自主学习者","grade":6,"term":"A","order":4,"minutes":6,"title":"写一张自主学习自评卡","subtitle":"用完整句子回顾、描述和计划。","topicIds":["tense.past-simple","tense.present-simple","tense.future"],"vocabulary":[{"word":"reflect","meaning":"反思"},{"word":"improve","meaning":"改进"},{"word":"step","meaning":"一步；步骤"}],"task":"用三句话给自己写自评：昨天做了什么、常用策略、明天的小计划。","cards":[{"title":"写一张自主学习自评卡","rule":"自评可以包含过去做了什么、平时怎样学习、接下来准备做什么。每句都要让时间和动词相互配合。","example":"I practised English yesterday.","translation":"我昨天练习了英语。"},{"title":"写一张自主学习自评卡","rule":"自评可以包含过去做了什么、平时怎样学习、接下来准备做什么。每句都要让时间和动词相互配合。","example":"I usually check my answers.","translation":"我通常检查自己的答案。"},{"title":"写一张自主学习自评卡","rule":"自评可以包含过去做了什么、平时怎样学习、接下来准备做什么。每句都要让时间和动词相互配合。","example":"I am going to try again tomorrow.","translation":"我明天准备再试一次。"}],"itemCount":9}');
INSERT INTO items VALUES('P1A-U01-L1.f1.choice',1,'P1A-U01-L1',1,'vocabulary.greetings','recognition','choice','{"id":"P1A-U01-L1.f1.choice","category":"vocabulary","title":"把问候送给朋友","context":"在校门口第一次见到Mia，向她打招呼。","prompt":"___, Mia.","type":"choice","choices":["Goodbye","Hello","Good night"],"gradeMin":1}','{"answers":["Hello"],"hint":"Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","explanation":"Hello, Mia. 你好，Mia。 Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","family":"fact-44b128824aeed9f0"}','published');
INSERT INTO items VALUES('P1A-U01-L1.f2.choice',1,'P1A-U01-L1',1,'vocabulary.greetings','recognition','choice','{"id":"P1A-U01-L1.f2.choice","category":"vocabulary","title":"把问候送给朋友","context":"早上走进教室，向老师问好。","prompt":"Good ___, Miss Li.","type":"choice","choices":["night","goodbye","morning"],"gradeMin":1}','{"answers":["morning"],"hint":"Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","explanation":"Good morning, Miss Li. 李老师，早上好。 Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","family":"fact-fc5f447443ad029a"}','published');
INSERT INTO items VALUES('P1A-U01-L1.f3.choice',1,'P1A-U01-L1',1,'vocabulary.greetings','recognition','choice','{"id":"P1A-U01-L1.f3.choice","category":"vocabulary","title":"把问候送给朋友","context":"放学离开时，向Ben告别。","prompt":"___, Ben.","type":"choice","choices":["Goodbye","Thanks","Sorry"],"gradeMin":1}','{"answers":["Goodbye"],"hint":"Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","explanation":"Goodbye, Ben. Ben，再见。 Hello和Hi用来打招呼；Good morning用于早上，Goodbye用于告别。","family":"fact-19b85276112e5d19"}','published');
