INSERT INTO items VALUES('P1A-U01-L2.f1.choice',1,'P1A-U01-L2',1,'grammar.be.present','recognition','choice','{"id":"P1A-U01-L2.f1.choice","category":"grammar","title":"说说我是谁","context":"Mia介绍自己：我是Mia。","prompt":"I ___ Mia.","type":"choice","choices":["is","am","are"],"gradeMin":1}','{"answers":["am"],"hint":"介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","explanation":"I am Mia. 我是Mia。 介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","family":"fact-e58c7f0416ae9e57"}','published');
INSERT INTO items VALUES('P1A-U01-L2.f2.choice',1,'P1A-U01-L2',1,'grammar.be.present','recognition','choice','{"id":"P1A-U01-L2.f2.choice","category":"grammar","title":"说说我是谁","context":"Ben介绍自己的名字。","prompt":"My name ___ Ben.","type":"choice","choices":["am","are","is"],"gradeMin":1}','{"answers":["is"],"hint":"介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","explanation":"My name is Ben. 我的名字是Ben。 介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","family":"fact-2d157a14c8c952da"}','published');
INSERT INTO items VALUES('P1A-U01-L2.f3.choice',1,'P1A-U01-L2',1,'grammar.pronouns.subject','recognition','choice','{"id":"P1A-U01-L2.f3.choice","category":"grammar","title":"说说我是谁","context":"向新朋友说明：我是Sam。","prompt":"___ am Sam.","type":"choice","choices":["I","You","He"],"gradeMin":1}','{"answers":["I"],"hint":"介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","explanation":"I am Sam. 我是Sam。 介绍自己可以用I am加名字，也可以用My name is加名字。I总是大写。","family":"fact-a0d78e6a9dccb97d"}','published');
