INSERT INTO items VALUES('P2A-U01-L1.f3.order',1,'P2A-U01-L1',1,'grammar.be.present','controlled-production','order','{"id":"P2A-U01-L1.f3.order","category":"grammar","title":"朋友名片上的小线索","context":"Mia和Ben是两位朋友。","prompt":"用词块搭出这句英语。","type":"order","tokens":["friends.","are","They"],"gradeMin":2}','{"answers":["They are friends."],"hint":"he表示他，she表示她，they表示他们或她们。介绍一个人常用is，介绍多个人用are。","explanation":"They are friends. 他们是朋友。 he表示他，she表示她，they表示他们或她们。介绍一个人常用is，介绍多个人用are。","family":"fact-04b60a207b878e7d"}','published');
