INSERT INTO items VALUES('P5A-U01-L3.f1.choice',1,'P5A-U01-L3',1,'grammar.past-simple','recognition','choice','{"id":"P5A-U01-L3.f1.choice","category":"tense","title":"did后面要回到原形","context":"询问Ben昨天有没有去公园。","prompt":"Did Ben ___ to the park yesterday?","type":"choice","choices":["went","goes","go"],"gradeMin":5}','{"answers":["go"],"hint":"一般过去时的行为动词问句和否定句用了did或did not后，主要动词回到原形；be动词另有was/were的规则。","explanation":"Did Ben go to the park yesterday? Ben昨天去公园了吗？ 一般过去时的行为动词问句和否定句用了did或did not后，主要动词回到原形；be动词另有was/were的规则。","family":"fact-42bf8df814a718a8"}','published');
